            { kind: "stack", children: [{ kind: "window", windowKindId: "drag-input", title: "Input" }] },
            { kind: "stack", children: [{ kind: "window", windowKindId: "drag-diff", title: "Diff" }] },

      if (control.kind === "toggle") {
