function createUICanvasAsyncLifecycle(): UICanvasAsyncLifecycle {
  let disposed = false;
  let cleanup: (() => void) | undefined;

  return {
    isDisposed: () => disposed,
    registerCleanup: (nextCleanup) => {
      cleanup = nextCleanup;
      if (disposed) {
        cleanup();
      }
    },
    dispose: () => {
      disposed = true;
      if (cleanup) {
        const fn = cleanup;
        cleanup = undefined;
        fn();
      }
    },
  };
}

